class AppError(Exception):
    pass

class DbError(AppError):
    pass

try:
    raise DbError("x")
except AppError as e:
    print(type(e).__name__, str(e))

class Ctx:
    def __enter__(self):
        print("in", end=" ")
        return self

    def __exit__(self, *exc):
        print("out", end=" ")
        return True

with Ctx():
    raise ValueError
print("after")

